sql:
SELECT DISTINCT meeting_id, meeting_title, meeting_date, speaker, turn_content
FROM v_speaker_turns
WHERE turn_content LIKE '%VJ Technologies%';

SELECT amount_currency, SUM(amount_value) AS total_amount 
FROM v_amounts 
GROUP BY amount_currency;

SELECT meeting_title, meeting_date, action_item_text
FROM v_action_items
ORDER BY meeting_date DESC;

SELECT DISTINCT v_dates.meeting_title, v_dates.date_resolved 
FROM v_dates 
ORDER BY v_dates.meeting_title, v_dates.date_resolved;

SELECT DISTINCT meeting_title, meeting_date, topic 
FROM v_topics 
WHERE source_type = 'topic' AND topic ILIKE '%GoEMON%';

SELECT meeting_id, meeting_title, meeting_date, passage_id, topic
FROM v_topics
WHERE source_type = 'topic' AND topic LIKE '%DX%';

SELECT meeting_id, meeting_title, meeting_date, person, action, deadline
FROM v_commitments
WHERE action ILIKE '%budget%';

SELECT meeting_id, meeting_title, meeting_date, person, action, deadline, deadline_date, status 
FROM v_commitments 
WHERE meeting_date = '2026-05-26';

SELECT meeting_id, meeting_title, meeting_date, amount_value, amount_unit, amount_currency, amount_context 
FROM v_amounts 
WHERE amount_value >= 1000;

SELECT SUM(amount_value) AS total_amount 
FROM v_amounts 
WHERE amount_context LIKE '%budget%';

SELECT speaker, turn_content, meeting_title, meeting_date 
FROM v_speaker_turns 
WHERE turn_content ILIKE '%GoEMON%';

SELECT DISTINCT meeting_title, question_text 
FROM v_open_questions 
ORDER BY meeting_title;

SELECT SUM(amount_value) 
FROM v_amounts 
WHERE amount_unit LIKE '%man%';

SELECT DISTINCT meeting_title 
FROM v_topics 
WHERE topic ILIKE '%AJ Technologies%' AND source_type = 'entity';

SELECT DISTINCT meeting_title 
FROM v_topics 
WHERE topic ILIKE '%ONE Financial Service%' AND source_type = 'entity';

SELECT meeting_title, person, action, deadline, deadline_date, status 
FROM v_commitments 
ORDER BY deadline_date ASC;

SELECT commitment_id, person, action, deadline, deadline_date 
FROM v_commitments 
WHERE deadline_date BETWEEN '2026-05-25' AND '2026-05-31';

SELECT meeting_title, meeting_date, action_item_text, importance_score 
FROM v_action_items 
ORDER BY importance_score DESC;
